import TablaConPaginacion from "../../Componentes/TablaConPaginacion/TablaConPaginacion";
import PlantillaPages from '../../Componentes/PlantillaPages/PlantillaPages'
import Pestanias from "../../Componentes/Pestanias/Pestanias";
import Boton from "../../Componentes/Boton/Boton";
import { useState, useEffect, useRef } from 'react'
import columnas from '../../Datos_Pruebas/Columnas_Compras.json'
import Compra from '../../Componentes/Formularios/Compra/Compra'
import Modal from '../../Componentes/Modal/Modal'
import PanelCompras from "../../Componentes/Paneles/PanelCompras/PanelCompras";
import { useValidarSesion } from "../../hooks/useValidarSesion";
import InformesCompras from "../../Componentes/Informes/InformesCompras";



export default function Compras({ }) {

  const { storeCargado, token, usuario } = useValidarSesion(); // obtener el token desde Zustand y validar inici de sesion sino lo manda a iniciar sesion




  //BOOLEANO DEFINE SI ES SUPERADMIN
  const esSuperAdmin = usuario?.rol?.[0].nombreRol === "superadmin";

  //ESTADO PARA DETERMINAR LA SUCURSAL
  const [idSucursalSeleccionada, setIdSucursalSeleccionada] = useState(
    esSuperAdmin ? null : usuario?.sucursal?.[0]?.id_sucursal || null
  );

  //BOOLEANO PARA PREGUNTAR SI EL USUARIO TIENE PERMISO DE HACER COMPRA
  const permisoComprar = usuario?.permisos?.some(
    (permiso) => permiso.nombrePermiso === 'comprar'
  ) ||
    usuario?.permisos_extra?.some(
      (permiso) => permiso.nombrePermiso === 'comprar'
    );

  //BOOLEANO PARA PREGUNTAR SI EL USUARIO TIENE PERMISO DE VER INFORME DE COMPRAS
  const permisoVerInforme = usuario?.permisos?.some(
    (permiso) => permiso.nombrePermiso === 'ver informe'
  ) ||
    usuario?.permisos_extra?.some(
      (permiso) => permiso.nombrePermiso === 'ver informe'
    );

  ////////////OBTENGO A TODOS LOS PROVEEDORES
  const [proveedores, setProveedores] = useState([]);

  const obtenerProveedores = () => {
  fetch(`${import.meta.env.VITE_API_BASE_URL}/api/proveedor`)
      .then(respuesta => respuesta.json())
      .then(datos => setProveedores(datos))
      .catch(e => console.log(e));
  };

  useEffect(() => {
    obtenerProveedores();
  }, []);




  ////////MANEJA MODAL NUEVA COMPRA
  const [modalNuevaCompra, setModalNuevaCompra] = useState(false); // Abre o cierra el modal nuevo prodcuto
  const manejaModalNuevaCompra = () => {
    setModalNuevaCompra(!modalNuevaCompra);

    if (modalNuevaCompra) {  //si el modal estaba abierto, actualiza los datos
      actualizarDatos();//acutaliza datos despues de cerrarse el modal
    }
  };


  const [datos, setDatos] = useState([]);
  const obtieneDatosFiltrados = (datosFiltrados) => {
    setDatos(datosFiltrados);

  };


  /////////// ESTADO PARA SABER CUANDO SE ESTA CARGANDO (SE ESTAN TRAYENDO LOS DATOS)
  const [cargando, setCargando] = useState(false);

  const manejaCargando = ((valor) => {
    setCargando(valor);
  });


  ///CREO UN PUNTERO USEREF PARA PASARSELO AL MODAL DE NUEVA COMPRA PARA QUE RECIBA y SE LO PASE
  /// A NUEVO PROVEEDOR, ASI CUANDO CREE UNO NUEVO, SEEJECUTA NUEVAMENTE LA FUNCION OBTENERPROVEEDORES CON ELNUEVO PROVEEDOR

  const actualizarProveedores = useRef(() => {
    obtenerProveedores();
  })

  ////ACTUALIZACION DE DATOS USANDO REF PARA INDICARLE AL COMPONENTE DE PANEL COMPRAS QUE ACTUALICE LA BUSQUEDA DESPUES DE CADA CRUD
  const panelComprasRef = useRef();

  const actualizarDatos = () => {
    if (panelComprasRef.current) {
      panelComprasRef.current.actualizarDatos();
    }
  };

  ///para traer los filtros del panelfiltros
  const [filtros, setFiltros] = useState({});


  ///////ESTADO Y FUNCION PARA MANEJAR EL MODAL DE INFORMES
  const [modalInformes, setModalInformes] = useState(false);
  const manejaModalInformes = ((valor) => {
    setModalInformes(valor);
  });




  //  PROTECCIÓN: si todavia no se cargo el store ni usuario, no reendreizar nada
  if (!storeCargado || !usuario || !token) {
    return <div className="__cargando_modal"></div>;
  }


  ////LAYOUT

  const header = <PanelCompras
    ref={panelComprasRef}
    onDatosFiltrados={obtieneDatosFiltrados}
    onManejaCargando={manejaCargando}
    proveedores={proveedores}
    token={token}
    onFiltros={setFiltros}
    esSuperAdmin={esSuperAdmin}
    onSeleccionarSucursal={setIdSucursalSeleccionada}
    permisoVerInforme={permisoVerInforme}
    onMostrarInformes={manejaModalInformes}
  >
  </PanelCompras>


  const main = <TablaConPaginacion columnas={columnas} datos={datos} itemsPorPagina={6} itemsPorPaginaOpcional
    cargando={cargando}
  ></TablaConPaginacion>

  const navigation = <Pestanias></Pestanias>

  const footer = <div style={{ display: "flex" }}>
    {permisoComprar && <Boton descripcion={"NUEVA"} onClick={manejaModalNuevaCompra} habilitado title="Realizar nueva compra"></Boton>}
    <Modal visible={modalNuevaCompra} titulo="Nueva Compra" funcion={manejaModalNuevaCompra} anchura={"800px"} >
      <Compra onGuardar={manejaModalNuevaCompra} id_sucursal={idSucursalSeleccionada} actualizarProveedores={actualizarProveedores} siguienteCompra={(datos[datos.length - 1]?.id_compra)}></Compra>
    </Modal>
    <Modal visible={modalInformes} titulo="Informe de Compras" funcion={() => manejaModalInformes(false)} anchura={"80%"} >
      <InformesCompras
        filtros={filtros}
        token={token}
        onCerrar={() => manejaModalInformes(false)}
      />
    </Modal>


  </div>

  return <PlantillaPages
    header={header}
    navigation={navigation}
    main={main}
    footer={footer}
    nombreUsuario={usuario?.nombre}
    apellidoUsuario={usuario?.apellido}
    sucursal={usuario?.sucursal?.[0]?.nombreSucursal}
    id_sucursal={idSucursalSeleccionada}
    rol={usuario?.rol?.[0]?.nombreRol}
    esSuperAdmin={esSuperAdmin}
    token={token}
  />;
}
