import { useEffect, useState } from "react";
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, LineChart, Line } from "recharts";
import "./InformesCompras.css";
import Boton from "../Boton/Boton";
import no_encontrado from "../../assets/no_encontrado.png";
import { useExportarDatos } from "../../hooks/useExportarDatos";
import TarjetaProducto from "../TarjetaProducto/TarjetaProducto";

export default function InformesCompras({ filtros, token, onCerrar }) {

  //HOOK PARA CONVERTIR DATOS EN EXCEL Y PDF
  const { exportarInformeComprasAExcel, exportarInformeComprasAPDF } = useExportarDatos();

  const manejarExportacion = (tipo) => {
    const datosExportacion = {
      metricas,
      comprasPorFecha,
      productosMasComprados,
      topProveedores
    };

    if (tipo === 'excel') {
      exportarInformeComprasAExcel(datosExportacion, 'informe_compras.xlsx', getPeriodoTexto());
    } else if (tipo === 'pdf') {
      exportarInformeComprasAPDF(datosExportacion, 'informe_compras.pdf', getPeriodoTexto());
    }
  };

  //FUNCIÓN PRIMERA LETRA DE UNA PALABRA EN MAYÚSCULAS
  const transformaMayusucula = (str) => {
    return str.replace(/\b\w/g, (char) => char.toUpperCase());
  };

  // Función para formatear moneda
  const formatearMoneda = (monto) => {
    return `$ ${monto.toLocaleString('es-AR', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    })}`;
  };

  const [metricas, setMetricas] = useState({
    total_comprado: 0,
    cantidad_compras: 0,
    productos_comprados: 0,
  });

  const [comprasPorFecha, setComprasPorFecha] = useState([]);
  const [productosMasComprados, setProductosMasComprados] = useState([]);
  const [topProveedores, setTopProveedores] = useState([]);
  const [cargando, setCargando] = useState(false);

  useEffect(() => {
    if (filtros && Object.keys(filtros).length > 0) obtenerInforme();
  }, [filtros]);

  const obtenerInforme = async () => {
    try {
      setCargando(true);
  const res = await fetch(`${import.meta.env.VITE_API_BASE_URL}/api/compra/informe`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Accept": "application/json",
          "Authorization": `Bearer ${token}`,
        },
        body: JSON.stringify(filtros),
      });

      if (!res.ok) throw new Error("Error al generar el informe");
      const data = await res.json();

      setMetricas(data.metricas);

      // Mantener Total como número para el gráfico
      const comprasFormateadas = data.compras_por_fecha.map(compra => ({
        fecha: compra.fecha,
        Total: compra.Total
      }));
      setComprasPorFecha(comprasFormateadas);

      // Transformar productos al guardar
      const productosTransformados = data.productos_mas_comprados.map(producto => ({
        ...producto,
        producto: transformaMayusucula(producto.producto)
      }));
      setProductosMasComprados(productosTransformados);

      // Transformar proveedores
      const proveedoresTransformados = data.top_proveedores.map(proveedor => ({
        ...proveedor,
        nombre: transformaMayusucula(proveedor.nombre)
      }));
      setTopProveedores(proveedoresTransformados);

    } catch (error) {
      console.error("Error al obtener informe:", error);
    } finally {
      setCargando(false);
    }
  };

  if (cargando) return <p>Cargando informe...</p>;

  // Producto y proveedor más destacado
  const topProducto = productosMasComprados[0];
  const topProveedor = topProveedores[0];

  // Formateo correcto de fechas
  const formatearFecha = (fechaISO) => {
    if (!fechaISO) return "";
    const [anio, mes, dia] = fechaISO.split("-");
    return `${dia}/${mes}/${anio}`;
  };

  const getPeriodoTexto = () => {
    const nombresMeses = [
      "Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio",
      "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"
    ];

    if (filtros.periodo_compras === 'Todas las compras') {
      return "Todas las Compras";
    } else if (filtros.periodo_compras === 'Ver compras desde el') {
      return `Desde ${formatearFecha(filtros.fecha_desde)} Hasta ${formatearFecha(filtros.fecha_hasta)}`;
    } else {
      return `${nombresMeses[Number(filtros.mes_compra) - 1]} del ${filtros.anio_compra}`;
    }
  };

  // Función para construir la URL completa de la imagen
  const construirUrlImagen = (rutaRelativa, esCombo, esSucursal) => {
    if (!rutaRelativa) return no_encontrado
    // Si ya contiene http, devuelve tal cual (por si acaso)
    if (rutaRelativa.startsWith('http')) return rutaRelativa
    // Si comienza con /, le agregamos el endpoint
    if (esCombo || esSucursal) {
      return `${API_ENDPOINT}${rutaRelativa}`
    }
  return `${import.meta.env.VITE_API_BASE_URL}/storage/${rutaRelativa}`
  }


  /////LAYOUT
  return (
    <div className="__informe_modal">
      <div className="__informe_contenido_compras">
        <h2 style={{ textAlign: 'center' }}>📊 Informe de Compras - {getPeriodoTexto()}</h2>

        {/* MÉTRICAS */}
        <div className="__informe_cards_compras">
          <div className="__card_informe_compras">
            <h4>Total Compras</h4>
            <p>{metricas.cantidad_compras}</p>
          </div>
          <div className="__card_informe_compras">
            <h4>Productos Comprados</h4>
            <p>{metricas.productos_comprados}</p>
          </div>
          <div className="__card_informe_compras">
            <h4>Total Invertido</h4>
            <p>$ {metricas.total_comprado.toLocaleString()}</p>
          </div>
        </div>

        {/* PRODUCTOS MÁS COMPRADOS */}
        <div className="__seccion_grafico_compras">
          <div className="__grafico_compras">
            <div className="separador"></div>
            <h3 style={{ marginBottom: "3rem" }}>Productos más comprados</h3>
            {productosMasComprados.length ?
              <ResponsiveContainer width="100%" height={300}>
                <BarChart data={productosMasComprados}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="producto" tick={{ fill: '#333', fontSize: 15 }}
                    angle={-25}
                    textAnchor="end"
                    height={100} />
                  <YAxis tick={{ fill: '#333' }} />
                  <Tooltip contentStyle={{ backgroundColor: '#f9f9f9', border: '2px solid #ddd', fontWeight: 'bold' }} />
                  <Bar dataKey="cantidad" fill="#9e030d" radius={[10, 10, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
              : <h3 style={{ display: 'flex', justifyContent: 'center', margin: '2rem 0rem' }}>No hay productos comprados en este período</h3>
            }
          </div>
          {topProducto && (
            <div className="__tarjeta_top_compras">
              <h4 style={{ marginBottom: "2rem" }}>🏆 Producto más comprado</h4>
              <TarjetaProducto
                nombre={topProducto.producto}
                cantidad={topProducto.cantidad}
                precio={topProducto.costo}
                imagen={construirUrlImagen(topProducto.foto)}
              >

              </TarjetaProducto>

            </div>
          )}
        </div>

        {/* PRINCIPALES PROVEEDORES */}
        <div className="__seccion_grafico_compras">
          <div className="__grafico_compras">
            <div className="separador"></div>
            <h3 style={{ marginBottom: "3rem" }}>Principales proveedores</h3>
            {topProveedores.length ?
              <ResponsiveContainer width="100%" height={300}>
                <BarChart data={topProveedores}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="nombre" tick={{ fill: '#333', fontSize: 15 }}
                    angle={-25}
                    textAnchor="end"
                    height={100} />
                  <YAxis tick={{ fill: '#333' }} />
                  <Tooltip contentStyle={{ backgroundColor: '#f9f9f9', border: '2px solid #ddd', fontWeight: 'bold' }}
                    formatter={(value) => formatearMoneda(value)}
                  />
                  <Bar dataKey="total_comprado" fill="#efc169" radius={[10, 10, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
              : <h3 style={{ display: 'flex', justifyContent: 'center', margin: '2rem 0rem' }}>No hay compras a proveedores en este período</h3>
            }
          </div>
          {topProveedor && (
            <div className="__tarjeta_top_compras">
              <h4 style={{ marginBottom: "2rem" }}>🏅 Proveedor principal</h4>
              <div>
                <p><strong>{topProveedor.nombre}</strong></p>
                <p>Compras: <strong>{topProveedor.compras}</strong></p>
                <p>Total: <strong>{formatearMoneda(topProveedor.total_comprado)}</strong></p>
              </div>
            </div>
          )}
        </div>

        {/* EVOLUCIÓN DE COMPRAS */}
        <div className="__seccion_grafico_compras">
          <div className="__grafico_compras">
            <div className="separador"></div>
            <h3 style={{ marginBottom: "3rem" }}>Evolución de compras</h3>
            {comprasPorFecha.length ?
              <ResponsiveContainer width="100%" height={300}>
                <LineChart data={comprasPorFecha}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="fecha" />
                  <YAxis />
                  <Tooltip
                    contentStyle={{ backgroundColor: '#f9f9f9', border: '2px solid #ddd', fontWeight: 'bold' }}
                    formatter={(value) => formatearMoneda(value)}
                    labelFormatter={(label) => `Fecha: ${label}`}
                  />
                  <Line type="monotone" dataKey="Total" stroke="#9e030d" strokeWidth={2} />
                </LineChart>
              </ResponsiveContainer>
              : <h3 style={{ display: 'flex', justifyContent: 'center', margin: '2rem 0rem' }}>No hay compras en este período</h3>
            }
          </div>
        </div>

        <div className="__informe_compraPorSucursal_footer">
          <Boton onClick={() => manejarExportacion('excel')} habilitado descripcion={"Descargar EXCEL"} />
          <Boton onClick={() => manejarExportacion('pdf')} habilitado descripcion={"Descargar PDF"} />
        </div>
      </div>
    </div>
  );
}