import Selector from '../../Selector/Selector';
import Input from "../../Input/Input";
import Tarjeta from '../../ComponentesFormulario/Tarjeta/Tarjeta';
import Radio from '../../Radio/Radio'
import './PanelCompras.css'
import { useEffect, useState, useRef, useImperativeHandle, forwardRef } from 'react';
import meses from '../../../Datos_Pruebas/Meses.json'
import { useForm, useWatch } from 'react-hook-form';
import leyseca from '../../../assets/leysecalogo.png'
import Boton from '../../Boton/Boton';

const PanelCompras = forwardRef(({ onDatosFiltrados, onManejaCargando, proveedores, token, esSuperAdmin, permisoVerInforme, onSeleccionarSucursal,onMostrarInformes,onFiltros }, ref) => {




    ///////FUNCION REF DEL PADRE QUE LE INDICA QUE OBTENGA LOS DATOS NUEVAMENTE DEL BACKKEND
    useImperativeHandle(ref, () => ({  //Con este metodo indicamos que metodos o propiedades estaran disponibles a traves del ref
        actualizarDatos: () => {
            obtenerDatosFiltrados();
        }
    }));

    //////////FUNCION PRIMMERA LETRA DE UNA PALABRA EN MAYUSCULAS
    const transformaMayusucula = (str) => {
        return str.replace(/\b\w/g, (char) => char.toUpperCase());
    };




    ////////// SELECCION DE LA OPCION DEL RADIO
    const [seleccion, setSeleccion] = useState('');//valor por defecto
    const manejarSeleccion = (valor) => { //funcion que se la pasa al input radio 
        setSeleccion(valor);             //el componente radio maneja la eleccion de un elemento y luego la retorna al padre
    };                                  //en este caso esta funcion, para setear la eleccion y tener us solo filtro de fecha activo



    // función para obtener la fecha en formato YYYY-MM-DD
    const obtenerFechaHoy = () => {
        const hoy = new Date();
        const year = hoy.getFullYear();
        const mes = String(hoy.getMonth() + 1).padStart(2, '0');
        const dia = String(hoy.getDate()).padStart(2, '0');
        return `${year}-${mes}-${dia}`;
    };

    ///////// HOOK FORM

    const { register, control, setValue, formState: { errors } } = useForm({
        defaultValues: {
            periodo_compras: "Todas las compras", // Valor por defecto
            tipo: "Nombre",
            fecha_desde: obtenerFechaHoy(),
            fecha_hasta: obtenerFechaHoy()

        }
    });

    // Observar en tiempo real el valor del radio button
    const periodoCompras = useWatch({ control, name: "periodo_compras" });


    const obtenerDatosFiltrados = async (data = filtro) => { //funcion que hace la consulta dependiendo los filtros
        onManejaCargando(true);
        try {

            const respuestaCompra = await fetch(`${import.meta.env.VITE_API_BASE_URL}/api/compra/filtro`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Accept': 'application/json',
                    'Authorization': `Bearer ${token}`,
                },
                body: JSON.stringify(data),
            });


            const datos = await respuestaCompra.json();

            const datosTransformados = datos.map(item => ({
                id_compra: item.id_compra,
                Proveedor: transformaMayusucula(item.nombreProveedor),
                Producto: transformaMayusucula(item.nombreProducto),
                Cantidad: item.cantidad,
                Fecha: new Date(item.fecha).toLocaleDateString(),
                Correo: item.correo,
                Telefono: item.telefono,
                TOTAL: `$ ${item.total}`
            }));
            onDatosFiltrados(datosTransformados);
            onFiltros(filtro);
        } catch (error) {
            console.error('Error en la solicitud:', error);
        } finally {
            onManejaCargando(false);
        }
    };



    /////////CAPTURAR LOS VALORES DEL FORMULARIO DINAMICAMENTE
    const filtro = useWatch({ control });


    //////PARA DARLE UN TIEMPO A LA BUSQUEDA POR NOMBRE O CODIGO
    const timeOutBusquedaRef = useRef(null);

    useEffect(() => {
        if (!filtro?.id_sucursal && esSuperAdmin) return;

        if (filtro?.busqueda) {
            clearTimeout(timeOutBusquedaRef.current);
            timeOutBusquedaRef.current = setTimeout(() => {
                obtenerDatosFiltrados(filtro);
            }, 2000);
        }
        else {
            obtenerDatosFiltrados(filtro);
        }

        return () => clearTimeout(timeOutBusquedaRef.current);

    }, [filtro])

    ///USE EFECTE PPARA DEVOLVER AL COMPONENTE PADRE EL VALOR DE LA SUCURSAL
    useEffect(() => {
        if (esSuperAdmin && filtro?.id_sucursal) {
            onSeleccionarSucursal(filtro.id_sucursal);
        }
    }, [filtro?.id_sucursal]);

    //aqui se guardan los años obtenidos del backend
    const [aniosCompra, setAniosCompra] = useState([]);

    //USEEFFECT PARA OBTENER TODOS LOS AñOS DE LAS COMPRAS

    useEffect(() => {
        const obtenerAnios = async () => {
            try {
                const respuesta = await fetch(`${import.meta.env.VITE_API_BASE_URL}/api/compra/anios`);
                const data = await respuesta.json();

                // El backend devuelve algo como: [2023, 2024, 2025]
                const opcionesAnios = data.map(anio => ({
                    label: anio.toString(),
                    value: anio.toString()
                }));

                setAniosCompra(opcionesAnios);
            } catch (error) {
                console.error('Error al obtener años de compras:', error);
            }
        };

        obtenerAnios();
    }, []);


    //////////// BUSCA SUCURSALES EN EL BACKEND
    const [sucursales, setSucursales] = useState([]);

    useEffect(() => {
        const obtenerSucursales = async () => {
            try {
                const respuesta = await fetch(`${import.meta.env.VITE_API_BASE_URL}/api/sucursal`);
                const datos = await respuesta.json();

                setSucursales(datos);

                // 👉 Si hay al menos una sucursal, establecerla como valor por defecto
                if (datos.length > 0) {
                    setValue("id_sucursal", datos[0].id_sucursal);
                }
            } catch (error) {
                console.log(error);
            }
        };

        obtenerSucursales();
    }, [setValue]);



    return (
        <>
            <div className='__panel_compras'>
                <div className='__logo_background'>
                    <img src={leyseca} alt="Ley Seca Logo" />
                </div>
                <form>
                    <div className='__columna1'>
                        <div className='__col1'>
                            <Tarjeta descripcion="Proveedor" forid="proveedor_panel">
                                <Selector opciones={proveedores.map(prov => ({ label: prov.nombre, value: prov.id_proveedor }))}
                                    id="proveedor_panel"
                                    opcionNula="Todos"
                                    {...register("proveedor")} />
                            </Tarjeta>
                            <Tarjeta descripcion="Buscar Producto" forid="busqueda">
                                <Input tipo="search" placeholder="Buscar" id="busqueda"
                                    {...register("busqueda")}
                                />
                            </Tarjeta>
                        </div>
                        {esSuperAdmin ? (<div className='__col1'>
                            <Tarjeta descripcion="Sucursal" forid="sucursal" mensajeError={errors.id_sucursal?.message}>
                                <Selector
                                    id="sucursal"
                                    opciones={sucursales.map(suc => ({ label: suc.nombre, value: suc.id_sucursal }))}
                                    {...register("id_sucursal", { required: { value: true, message: "Ingrese Sucursal" } })}
                                    opcionDefecto
                                />
                            </Tarjeta>
                            <Tarjeta descripcion="Por Codigo o Nombre" forid="tipo_busqueda">
                                <Selector opciones={[{ label: "Codigo", value: "Codigo" }, { label: "Nombre", value: "Nombre" }]}
                                    id="tipo_busqueda"
                                    opcionDefecto
                                    {...register("tipo")} />
                            </Tarjeta>
                        </div>) : (<div className='__col2'>
                            <Tarjeta descripcion="Por Codigo o Nombre" forid="tipo_busqueda">
                                <Selector opciones={[{ label: "Codigo", value: "Codigo" }, { label: "Nombre", value: "Nombre" }]}
                                    id="tipo_busqueda"
                                    opcionDefecto
                                    {...register("tipo")} />
                            </Tarjeta>
                        </div>)}

                    </div>
                    <div className='__columna2'>
                        <div className='__col1'>
                            <div className='__linea_vertical'></div>
                            <Radio opciones={["Compras del mes de", "Ver compras desde el", "Todas las compras"]}
                                name="periodo_compras"
                                value={periodoCompras}
                                onChange={(valor) => setValue("periodo_compras", valor)} // Actualiza el valor en hook form
                            ></Radio>
                        </div>
                        <div className='__col2'>
                            <div className='__fila1'>
                                <Selector opciones={meses}
                                    id="mes_compra"
                                    deshabilitado={periodoCompras !== "Compras del mes de"}
                                    {...register("mes_compra")}
                                />
                                
                                <Selector opciones={aniosCompra}
                                    id="anio_compra"
                                    deshabilitado={periodoCompras !== "Compras del mes de"}
                                    {...register("anio_compra")}
                                />
                            </div>
                            <div className='__fila2'>
                                <Input tipo="date"
                                    id="fecha_desde"
                                    deshabilitado={periodoCompras !== "Ver compras desde el"}
                                    {...register("fecha_desde")}
                                ></Input>
                                <label>al</label>
                                <Input tipo="date"
                                    id="fecha_hasta"
                                    deshabilitado={periodoCompras !== "Ver compras desde el"}
                                    {...register("fecha_hasta")}
                                ></Input>
                            </div>
                        </div>
                        <div className='__col3'>
                            {permisoVerInforme && <Boton habilitado descripcion="Informe de Compras" onClick={() => onMostrarInformes(true)} title="Ver métricas de compra de esta sucursal"></Boton>}
               
                        </div>
                    </div>
                </form>

            </div>

        </>
    )
}); export default PanelCompras;